void handleSave(void) {
  if (server.hasArg("ssid") && server.hasArg("pass")) {
    String ssid = server.arg("ssid");
    String pass = server.arg("pass");
    
    // Log Case 1: Print new SSID name upon successful web form submission
    SERIAL_PORT.println("\n====================================");
    SERIAL_PORT.println("PROV_SUCCESS: Device successfully provisioned!");
    SERIAL_PORT.print("Target SSID Name: ");
    SERIAL_PORT.println(ssid);
    SERIAL_PORT.println("Saving to LittleFS and rebooting system...");
    SERIAL_PORT.println("====================================");

    File f = LittleFS.open(config_file, "w");
    if (f) {
      f.println(ssid);
      f.println(pass);
      f.close();
      
      // Matching submission layout style block
      String html = "<html><head><meta name='viewport' content='width=device-width, initial-scale=1.0'>";
      html += "<style>body{font-family:'Arial',sans-serif;background:rgb(29,49,72);color:#ffffff;display:flex;justify-content:center;align-items:center;min-height:100vh;margin:0;}";
      html += ".card{background:rgba(255,255,255,0.08);padding:30px;border-radius:12px;border:1px solid rgba(255,255,255,0.15);text-align:center;max-width:350px;box-shadow:0 10px 25px rgba(0,0,0,0.3);}</style></head>";
      html += "<body><div class='card'><h3 style='margin-bottom:10px;font-size:1.3rem;'>Credentials Saved!</h3><p style='color:rgba(255,255,255,0.7);font-size:0.95rem;'>Connecting to network... Device rebooting.</p></div></body></html>";
      
      server.send(200, "text/html", html);
      SERIAL_PORT.printf("Credentials Saved! Connecting...\r\n");
      delay(2000);
      watchdog_reboot(0, 0, 0); 
    } else {
      server.send(500, "text/plain", "File system error.");
      SERIAL_PORT.printf("File system error.\r\n");
    }
  }
}

bool handleCaptivePortal(void) {
  String hostHeader = server.hostHeader();
  if (hostHeader != "192.168.4.1" && hostHeader != "picow.local") {
    server.sendHeader("Location", "192.168.4", true);
    server.send(302, "text/plain", ""); 
    return true;
  }
  return false;
}

bool loadSavedWiFi(void) {
  if (!LittleFS.exists(config_file)) return false;
  File f = LittleFS.open(config_file, "r");
  if (!f) return false;
  
  String ssid = f.readStringUntil('\n');
  String pass = f.readStringUntil('\n');
  f.close();
  
  ssid.trim();
  pass.trim();

  SERIAL_PORT.println();
  SERIAL_PORT.print("Attempting connection to saved network: ");
  SERIAL_PORT.println(ssid);
  
  // Create a unique STA HOSTNAME using the last 2 macAddr bytes
  // "XRPBeta_abcd", "XRP_abcd", "CETAIoT_abcd"
  WiFi.macAddress(macAddress);     // read/save the mac address of the radio
  #if defined(ARDUINO_RASPBERRY_PI_PICO_W)
  sprintf(sta_hostname, "CETAIoT-%02x%02x", macAddress[4], macAddress[5]);
  #elif defined(ARDUINO_SPARKFUN_XRP_CONTROLLER)
  sprintf(sta_hostname, "XRP-%02x%02x", macAddress[4], macAddress[5]);
  #elif defined(ARDUINO_SPARKFUN_XRP_CONTROLLER_BETA)
  sprintf(sta_hostname, "XRPBeta-%02x%02x", macAddress[4], macAddress[5]);
  #else
   #error Unsupported board selection
  #endif

  WiFi.setHostname(sta_hostname);
  WiFi.mode(WIFI_STA);
  WiFi.begin(ssid.c_str(), pass.c_str());
  
  int attempts = 0;
  while (WiFi.status() != WL_CONNECTED && attempts < 20) {
    #if defined(ARDUINO_RASPBERRY_PI_PICO_W) || defined(ARDUINO_SPARKFUN_XRP_CONTROLLER)
      digitalWrite(NETWORK_STAT_LED_PIN, 1);
      delay(100);
      digitalWrite(NETWORK_STAT_LED_PIN, 0);
      delay(100);
      digitalWrite(NETWORK_STAT_LED_PIN, 1);
      delay(100);
      digitalWrite(NETWORK_STAT_LED_PIN, 0);
      delay(100);
      digitalWrite(NETWORK_STAT_LED_PIN, 1);
      delay(100);
      digitalWrite(NETWORK_STAT_LED_PIN, 0);
      delay(100);
    #else
      delay(600);
    #endif  
    attempts++;
  }
  if (WiFi.status() == WL_CONNECTED) {
    
    // Print current network metrics when loading successfully from memory
    SERIAL_PORT.println("\n====================================");
    SERIAL_PORT.print("STA_SUCCESS: Connected to saved network: ");
    SERIAL_PORT.println(WiFi.SSID()); // Pulls current active name string directly from router core
    SERIAL_PORT.print("Assigned IP Address: ");
    SERIAL_PORT.println(WiFi.localIP());
    SERIAL_PORT.print("STA Hostname: ");
    SERIAL_PORT.println(sta_hostname);
    SERIAL_PORT.println("====================================");
    return true;
  }
  else {
    
    SERIAL_PORT.println("\nConnection failed or timed out.");
    return false;
  }
}

void startConfigurationAP(void) {
  SERIAL_PORT.println("\nSwitching to Configuration AP Mode...");
  WiFi.mode(WIFI_AP);
  WiFi.softAPConfig(apIPAddr, apGateway, apSubnet);

  // Select the "quietest non-overlapping" WiFi channel to start the network (1, 6, or 11)
  ap_channel = selectBestClassroomChannel();
  
  // Create a unique AP SSID, and AP Passphrase using the last 2 macAddr bytes
  // "XRPBeta_abcd", "XRP_abcd", "CETAIoT_abcd"
  // Note: the WiFi passphrase is set to match the SSID
  WiFi.macAddress(macAddress);     // read/save the mac address of the radio
  #if defined(ARDUINO_RASPBERRY_PI_PICO_W)
  sprintf(ap_ssid, "CETAIoT_%02x%02x", macAddress[4], macAddress[5]);
  sprintf(ap_pass, "CETAIoT_%02x%02x", macAddress[4], macAddress[5]);
  #elif defined(ARDUINO_SPARKFUN_XRP_CONTROLLER)
  sprintf(ap_ssid, "XRP_%02x%02x", macAddress[4], macAddress[5]);
  sprintf(ap_pass, "XRP_%02x%02x", macAddress[4], macAddress[5]);
  #elif defined(ARDUINO_SPARKFUN_XRP_CONTROLLER_BETA)
  sprintf(ap_ssid, "XRPBeta_%02x%02x", macAddress[4], macAddress[5]);
  sprintf(ap_pass, "XRPBeta_%02x%02x", macAddress[4], macAddress[5]);
  #else
   #error Unsupported board selection
  #endif

  if(WiFi.beginAP(ap_ssid, ap_pass, ap_channel) == WL_CONNECTED)
  {
    SERIAL_PORT.print("Access Point SSID Started: ");
    SERIAL_PORT.println(ap_ssid);
    SERIAL_PORT.print("IP Addr: ");
    SERIAL_PORT.print(WiFi.softAPIP());
    SERIAL_PORT.print(" WiFi Channel: ");
    SERIAL_PORT.println(ap_channel);
    SERIAL_PORT.println("Connect your phone/computer to view the portal.");
  } 
  else 
  {
    SERIAL_PORT.println("AP failed to start!.");
  }
  
  // Start the background DNS intercept handler
  dnsServer.start(DNS_PORT, "*", IPAddress(192, 168, 4, 1));
  
  server.on("/", handleRoot);
  server.on("/save", HTTP_POST, handleSave);
  
  // Capture fallback requests from operating system network verification background utilities
  server.onNotFound([]() {
    if (!handleCaptivePortal()) {
      handleRoot();
    }
  });
  
  server.begin();
}

void checkResetButton(void) {
  static int lastButtonState = HIGH;
  static unsigned long buttonPressedTime = 0;
  static bool isResetting = false;

  int currentButtonState = digitalRead(RESET_BUTTON_PIN);

  if (currentButtonState != lastButtonState) {
    delay(DEBOUNCE_DELAY); 
    currentButtonState = digitalRead(RESET_BUTTON_PIN);
    if (currentButtonState == LOW) {
      buttonPressedTime = millis();
    }
  }

  if (currentButtonState == LOW && !isResetting) {
    if (millis() - buttonPressedTime >= HOLD_TIME) {
      isResetting = true;
      if (LittleFS.exists(config_file)) {
        LittleFS.remove(config_file);
      }
      SERIAL_PORT.printf("\r\nDeleting saved WiFi Credentials...and Rebooting!\r\n");
      delay(1000);
      watchdog_reboot(0, 0, 0);
    }
  }
  lastButtonState = currentButtonState;
}

void nmStartConnection(void)
{
  SERIAL_PORT.printf("\r\n[Network Manager] Triggering connection to SSID: %s ...\r\n", nmNetSSID);
  WiFi.begin(nmNetSSID, nmNetPassword);
  nmReconnectStartTime = millis();
  nmState = NETWORK_STATE_ATTEMPTING_CONNECTION;
}